"Ton voyage reste sur ce téléphone avec toutes ses photos. Tu ne recevras plus les modifications des autres.":"여행은 모든 사진과 함께 이 휴대폰에 남아요. 다른 사람의 변경 사항은 더 이상 받지 않아요.",
