"🚪 Quitter le voyage partagé":"🚪 공유 여행 나가기",
"ℹ️ Personne d’autre n’a ouvert ce voyage depuis 2 mois : tu pourras effacer son dossier du serveur.":"ℹ️ 2개월 동안 아무도 이 여행을 열지 않았어요: 서버에서 폴더를 지울 수 있어요.",
"Personne d’autre n’utilise ce voyage partagé depuis 2 mois.":"2개월 동안 다른 사람이 이 공유 여행을 사용하지 않았어요.",
