"🔑 Nouveau lien créé":"🔑 새 링크를 만들었어요",
"{0} abonné(s) ont une ancienne version de l’appli et ne reçoivent pas le nouveau lien automatiquement.":"팔로워 {0}명은 앱이 옛 버전이라 새 링크를 자동으로 받지 못해요.",
