"Facultatif : sauvegarde en ligne de tous tes voyages, pour les retrouver sur ton autre téléphone ou ta tablette avec le même code. Hors connexion, tout reste sur le téléphone et part dès que le réseau revient.":"선택 사항: 모든 여행을 온라인에 백업해서 같은 코드로 다른 휴대폰이나 태블릿에서 볼 수 있어요. 오프라인일 때는 모두 휴대폰에 남았다가 네트워크가 돌아오면 바로 전송됩니다.",
"Pour partager un seul voyage, inutile : dans le voyage, touche Partager. Seul ce voyage est alors stocké sur le serveur, tes autres voyages restent sur ton téléphone.":"여행 하나만 공유하려면 필요 없어요: 여행에서 공유를 누르세요. 그러면 그 여행만 서버에 저장되고, 다른 여행은 휴대폰에 남아요.",
