"Les étapes, les récits et les photos du voyage. Ajoute tes propres souvenirs avec leurs photos.":"여행의 경유지, 여행기, 사진. 사진과 함께 나만의 추억을 추가하세요.",
"📤 Tout renvoyer (voyage + photos)":"📤 모두 다시 보내기 (여행 + 사진)",
"🔑 Nouveau code (repartir à neuf)":"🔑 새 코드 (처음부터)",
"Créer un nouveau code pour « {0} » ?\n\nLe voyage, ses fiches et ses photos repartent sur le serveur sous ce nouveau code. Les autres téléphones doivent ensuite le rejoindre avec le nouveau code (Mes voyages → Rejoindre un voyage partagé).":"“{0}”의 새 코드를 만들까요?\n\n여행과 항목, 사진이 새 코드로 서버에 다시 올라갑니다. 그 뒤 다른 휴대폰은 새 코드로 다시 참여해야 해요 (내 여행 → 공유 여행 참여).",
"⚠️ Le voyage n’a pas pu être envoyé sous le nouveau code : {0}\nRéessaie avec « Tout renvoyer » quand la connexion est bonne.":"⚠️ 새 코드로 여행을 보내지 못했어요: {0}\n연결이 좋을 때 “모두 다시 보내기”로 다시 시도하세요.",
"✅ Voyage en ligne : le code peut être donné":"✅ 여행이 온라인에 있어요: 코드를 공유할 수 있어요",
"Ce voyage avait déjà un code (effacé du serveur, par exemple) ? Colle-le ici pour le réutiliser : les autres téléphones le retrouveront.\nSinon laisse vide : un nouveau code sera créé.":"이 여행에 예전 코드가 있었나요 (예: 서버에서 삭제됨)? 여기에 붙여 넣으면 다시 쓸 수 있고, 다른 휴대폰에서도 다시 찾을 수 있어요.\n아니면 비워 두세요: 새 코드가 만들어져요.",
"🗑 Supprimé du serveur : {0} fiche(s) et {1} photo(s).\nTes données restent sur ce téléphone.\n\nGarder le code sur ce téléphone ?\nOK = je garde le code : tu pourras tout renvoyer plus tard avec le même code (bouton « Tout renvoyer »).\nAnnuler = j’oublie ce code ici.":"🗑 서버에서 삭제됨: 항목 {0}개, 사진 {1}장.\n데이터는 이 휴대폰에 남아 있어요.\n\n이 휴대폰에 코드를 남길까요?\n확인 = 코드 유지: 나중에 같은 코드로 모두 다시 보낼 수 있어요 (“모두 다시 보내기” 버튼).\n취소 = 여기서 이 코드를 잊기.",
"Le code est gardé. Pour tout remettre sur le serveur : {0} → « Tout renvoyer ».":"코드를 유지했어요. 서버에 모두 되돌리려면: {0} → “모두 다시 보내기”.",
"Mes voyages → le voyage → code":"내 여행 → 여행 → 코드",
"📤 Voyage ou photos non arrivés ?":"📤 여행이나 사진이 안 왔나요?",
