"Tout est enregistré sur ce téléphone ({0} Ko){1}. L’export reste ta copie de secours, et il contient aussi l’archive 2026.":"모두 이 휴대폰에 저장되어 있어요 ({0} KB){1}. 내보내기는 여전히 백업 사본이며, 2026 보관함도 들어 있어요.",
