"Le carnet partagé contient déjà {0} fiches.\n\nOK = utiliser le carnet partagé (recommandé pour rejoindre : ce téléphone garde seulement ses profils).\nAnnuler = fusionner les deux carnets.":"공유 수첩에 이미 항목이 {0}개 있어요.\n\n확인 = 공유 수첩 사용 (참여할 때 권장: 이 휴대폰은 프로필만 유지).\n취소 = 두 수첩 합치기.",
"☁️ Synchro activée":"☁️ 동기화 켜짐",
"Désactiver la synchro sur ce téléphone ? Les données restent ici.":"이 휴대폰에서 동기화를 끌까요? 데이터는 여기 남아요.",
"Rejoins notre carnet de voyage 🧳\n{0}\nCode du carnet : {1}\n(⚙️ Partage → colle le code → Activer la synchro)":"우리 여행 수첩에 함께해요 🧳\n{0}\n수첩 코드: {1}\n(⚙️ 공유 → 코드 붙여넣기 → 동기화 켜기)",
"📤 Export prêt":"📤 내보내기 준비 완료",
"Ce fichier ne contient pas de carnet de voyage.":"이 파일에는 여행 수첩이 없어요.",
"Le voyage 2027 existe déjà ici. Le remplacer par celui du fichier ?":"2027년 여행이 이미 여기 있어요. 파일의 것으로 바꿀까요?",
"Fichier illisible : ce n’est pas un export JSON valide.":"읽을 수 없는 파일: 올바른 JSON 내보내기 파일이 아니에요.",
"Le fichier contient aussi l’archive 2026. La restaurer ?":"파일에 2026 보관함도 들어 있어요. 복원할까요?",
"Ce carnet n’est pas synchronisé : rien n’est stocké sur le serveur.":"이 수첩은 동기화되지 않았어요: 서버에 저장된 것이 없어요.",
"Demander l’effacement de ce carnet sur le serveur ?\n\nToutes ses données en ligne seront supprimées, pour TOUS ses membres. Un e-mail va être préparé : il contient seulement l’identifiant chiffré du carnet, jamais son code.":"서버에서 이 수첩의 삭제를 요청할까요?\n\n온라인 데이터가 모든 멤버에게서 삭제돼요. 이메일이 준비되며, 여기에는 수첩의 암호화된 ID만 들어 있고 코드는 절대 들어가지 않아요.",
"Les données restent sur le serveur partagé, tu pourras le rejoindre à nouveau avec le code.":"데이터는 공유 서버에 남아 있어서 코드로 다시 참여할 수 있어요.",
