"Réserve chez la compagnie, puis dans le carnet :":"항공사에서 예약한 뒤 수첩에서:",
"Résas → Trajets":"예약 → 교통",
", ouvre le vol et remplis la compagnie, les horaires, le prix et le lien de réservation. Le budget et « qui doit quoi » se mettent à jour tout seuls.":", 항공편을 열고 항공사, 시간, 가격, 예약 링크를 채우세요. 예산과 “누가 얼마 줘야 하나”는 자동으로 업데이트돼요.",
"💡 Le premium utilise des services payants à quota : garde-le pour tes vraies dates, et repasse en soft pour flâner.":"💡 프리미엄은 사용량 제한이 있는 유료 서비스를 써요: 실제 여행 날짜를 위해 아껴 두고, 그냥 둘러볼 때는 소프트로 돌아가세요.",
"QR code de l’appli":"앱 QR 코드",
"📤 Partager l’appli à un ami":"📤 친구에게 앱 공유",
"Ton ami scanne ce code avec l’appareil photo de son téléphone, puis installe l’appli sur son écran d’accueil.":"친구가 휴대폰 카메라로 이 코드를 스캔한 뒤 홈 화면에 앱을 설치해요.",
"📤 Envoyer le lien":"📤 링크 보내기",
