": même nom pour ceux qui partagent un porte-monnaie (ex. « Anthony & Claire ») : « qui doit quoi » se calcule alors entre foyers.":": 지갑을 같이 쓰는 사람은 같은 이름(예: “Anthony & Claire”)으로: 그러면 “누가 얼마 줘야 하나”가 가구 단위로 계산돼요.",
