"Ancien lien abonnés retrouvé : {0} commentaire(s) récupéré(s).":"예전 팔로워 링크를 찾았어요: 댓글 {0}개를 되찾았어요.",
"{0} abonné(s) doivent recevoir ton lien actuel.":"팔로워 {0}명에게 현재 링크를 보내야 해요.",
"👀 Je suis un proche":"👀 지인이에요",
